arguments.command:
cd /tmp/vally-eval-trial-69MhzR && mkdir -p tests/CheckoutPricing.UnitTests/Acceptance && cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier
{
    Standard,
    Gold
}

public sealed class CalculatePayableTotal
{
    public decimal Execute(CustomerTier tier, decimal subtotal) => subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Acceptance/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Acceptance;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void S1_GoldCustomerReceivesTheApprovedDiscount()
    {
        var total = new CalculatePayableTotal().Execute(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --verbosity quiet 2>&1 | tail -20

